<script setup>
import {ref,onMounted} from 'vue'; import Header from '@/components/header.vue'; import Sidebar from '@/components/sidebar.vue'; import Breadcrumb from '@/components/breadcrumb.vue'; import Button from '@/components/ui/button.vue'; import {list,remove} from '@/services/school_groups'
const groups=ref([]),error=ref(''); const load=async()=>{try{groups.value=(await list()).school_groups||[]}catch(e){error.value='Não foi possível carregar as turmas'}}; const destroy=async id=>{if(confirm('Excluir esta turma?')){await remove(id);await load()}}; onMounted(load)
</script>
<template><div class="min-h-screen"><Header/><div class="flex flex-col md:flex-row"><Sidebar activePage="turmas"/><main class="flex-1 p-6"><Breadcrumb :items="[{label:'Home',href:'/home'},{label:'Administrador'},{label:'Turmas'}]"/><div class="flex justify-between items-center mb-6"><h1 class="text-2xl font-bold">Turmas</h1><Button to="/administrador/turmas/novo" customClass="bg-green-600">Nova turma</Button></div><p class="text-red-600">{{error}}</p><div class="bg-white rounded-md shadow overflow-auto"><table class="min-w-full"><thead class="bg-gray-100"><tr><th class="p-3 text-left">ID</th><th class="p-3 text-left">Nome</th><th class="p-3 text-left">Identificador</th><th class="p-3">Ações</th></tr></thead><tbody><tr v-for="g in groups" :key="g.id" class="border-t"><td class="p-3">{{g.id}}</td><td class="p-3">{{g.name}}</td><td class="p-3">{{g.identifier}}</td><td class="p-3 flex gap-2"><Button :to="`/administrador/turmas/editar/${g.id}`" customClass="bg-blue-600">Editar</Button><Button @click="destroy(g.id)" customClass="bg-red-600">Excluir</Button></td></tr></tbody></table></div></main></div></div></template>
